(3183, 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships', 'University of Tasmania — International Scholarships hub (2027 line-up; no TIS listed)', 'www.utas.edu.au', 'scholarship', '2026-10-30 00:00:00', true, true);

-- 2) NEW 1004 (Tasmanian International Merit Scholarship)
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, degree_levels, eligible_majors, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, eligible_countries, funding_type, tuition_coverage, living_allowance, travel_allowance, accommodation, application_fee, english_requirements, required_documents, application_url, opening_date, deadline_date, deadline_type, deadline_range_start, deadline_range_end, rounds, recurrence, expected_opening_period, expected_deadline_period, application_status, last_verified_at, last_updated_at, verification_status, source_reliability, source_url, notes, is_active, university_id, award_amount, award_currency, award_period, award_basis) VALUES
(1004, 'Tasmanian International Merit Scholarship', 'University of Tasmania', 'Australia', 'Partial Tuition', 0, 'No separate scholarship application or closing date — you are automatically assessed when you apply to study at the University of Tasmania and the outcome is stated in your offer letter; the operative dates are the university admission closing dates for your intake.', '["Bachelor''s","Master''s"]', '["All Majors"]', NULL, NULL, false, true, 'The Tasmanian International Merit Scholarship is the University of Tasmania''s automatically-assessed merit award for commencing international students: a 30% reduction in registered tuition fees for the standard duration of the course (up to five years full-time equivalent), applied as a tuition fee credit after the census date of each study period. There is no separate scholarship form — the Admissions Team assesses every applicant from the final results of their highest-level qualification of at least one year''s duration when they apply for an eligible undergraduate or postgraduate coursework degree, and the outcome is included in the offer letter. The published benchmark is a result equivalent to 10 ATAR points above the course''s minimum entry rank: the university''s equivalency tables are calibrated on a course with a 65 ATAR minimum (so a 75 ATAR-equivalent benchmark, e.g. IB 27 or an A-level score of 9), and courses with higher entry ranks carry higher scholarship benchmarks; on the university''s diploma/degree grading-scale tables the minimum attainment is 3.3 on a 4.0 GPA scale (or a prior UTAS degree GPA of 5.25/7). Applicants who fall short of the Merit benchmark are automatically assessed for other UTAS international scholarships, and those who meet it may also be invited to compete for the 50% Tasmanian Aurora Excellence Scholarship (record 1005).', 'To be eligible you must be classified as an international student, be commencing study at the University of Tasmania for the first time in an eligible full-time undergraduate (including honours) or postgraduate coursework degree, hold a valid offer, meet the admission and English language requirements, and meet the published academic benchmark on your highest-level qualification of at least one year. Excluded: Bachelor of Medical Science and Doctor of Medicine; Bachelor/Advanced Diploma of Applied Science (Nautical Science) and (Marine Engineering); Master of Psychology (Clinical), Master of Physiotherapy, Master of Speech Pathology and Master of Occupational Therapy; fully online, foundation, non-award, micro-credential, single-unit and exchange study; government-sponsored students (unless expressly approved); study through the International Pathway College, through an articulation partner with its own fee arrangement, or at locations outside Australia (unless approved). You must not hold another University of Tasmania tuition fee scholarship or external sponsorship unless expressly approved. To keep the award you must remain enrolled full-time in an eligible course past each census date, meet academic progression requirements and comply with student visa conditions.', 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/tasmanian-international-merit-scholarship', '["All"]', 'Merit-based', 'Partial tuition (30% fee reduction)', NULL, NULL, NULL, NULL, 'No fixed IELTS score is published for this scholarship; English requirements are set at course level (check the official course page for your programme).', '["International Student Application for an eligible University of Tasmania undergraduate or postgraduate coursework degree (no separate scholarship form)","Certified final academic documentation of your highest-level qualification of at least one year''s duration"]', 'https://www.utas.edu.au/study/apply/international-students', NULL, NULL, 'automatic', NULL, NULL, '[]', 'annual', 'Rolling — assessed with each admission application for the next intake', 'Course application closing dates for each intake (no separate scholarship deadline)', 'open', '2026-10-30 04:00:00+05', '2026-10-30 04:00:00+05', 'verified', 10, 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/tasmanian-international-merit-scholarship', 'NEW in Enrichment Batch 40 (2026-10-30), written from the first-hand read of the university''s official Tasmanian International Merit Scholarship page (source 3181, including the 2027 Terms and Conditions and grading-scale tables) and the current International Scholarships hub (source 3183). This is the mass automatically-assessed merit route in UTAS''s 2027 line-up; record 761 (Tasmanian International Scholarship, 25%) was retired in the same batch because the TIS name no longer appears in the published line-up — this record is a separately-named, individually verified scheme, not a rewrite of 761. The page notes that intakes to 2026 ran under previous Merit guidelines. Amount convention mirrors records 676/761: the published percentage reduction stored as award_amount=30 (AUD, per year, variable) with a 0 USD value because a percentage has no published dollar figure. min_gpa/min_ielts left NULL: eligibility is set by an ATAR-equivalent benchmark relative to each course''s entry rank (grading-scale minima such as 3.3/4.0 or 5.25/7 are course-band-dependent and are recorded in the narrative, not as structured cutoffs). deadline_type=automatic with no deadline_date: no separate application exists; assessment happens during admission and the outcome is stated in the offer letter.', true, 290, 30, 'AUD', 'year', 'variable');

-- 3) NEW 1005 (Tasmanian Aurora Excellence Scholarship)
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, degree_levels, eligible_majors, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, eligible_countries, funding_type, tuition_coverage, living_allowance, travel_allowance, accommodation, application_fee, english_requirements, required_documents, application_url, opening_date, deadline_date, deadline_type, deadline_range_start, deadline_range_end, rounds, recurrence, expected_opening_period, expected_deadline_period, application_status, last_verified_at, last_updated_at, verification_status, source_reliability, source_url, notes, is_active, university_id, award_amount, award_currency, award_period, award_basis) VALUES
(1005, 'Tasmanian Aurora Excellence Scholarship', 'University of Tasmania', 'Australia', 'Partial Tuition', 0, 'By invitation after you receive an offer: Semester 1 2027 applications opened 14 September 2026 and close 15 November 2026; Semester 2 2027 closes 30 April 2027 (opening date to be confirmed).', '["Bachelor''s","Master''s"]', '["All Majors"]', NULL, NULL, false, true, 'The Tasmanian Aurora Excellence Scholarship is the University of Tasmania''s top competitive award for new international students: a 50% reduction in registered tuition fees for the standard duration of the course (up to five years full-time equivalent), applied as a tuition fee credit after the census date of each study period. It is for international students commencing the first year of a full-time undergraduate or coursework master''s program from 2027. There is no open application portal — students who are eligible for the 30% Tasmanian International Merit Scholarship (record 1004) are invited to apply for Aurora after they receive their offer, and selection is competitive: applicants are scored on whether they meet strict minimum academic requirements and on a personal statement plus interview. The published academic floor is a 90 ATAR equivalent for secondary-school leavers (the university''s equivalency table covers school certificates from named countries — applicants from countries not listed, such as Uzbekistan, are directed to contact the university for the required score) and, for diploma/degree study, a prior UTAS GPA of 6.5/7 or a grading-scale equivalent such as 3.7 on a 4.0 scale. Aurora sits at the top of UTAS''s 2027 international scholarship line-up, above the automatically-assessed Merit (30%) and Access (20%) scholarships.', 'Eligibility: be classified as an international student; be commencing the first year of an eligible full-time undergraduate (including honours) or postgraduate coursework degree at the University of Tasmania from 2027; hold a valid offer and be invited to apply after being assessed as eligible for the Tasmanian International Merit Scholarship; meet the admission and English language requirements and the published minimum academic requirements; and complete the scholarship application form and a personal statement of 300-500 words and attend an interview. Excluded programs: Bachelor of Medical Science and Doctor of Medicine, Bachelor of Nursing (Hobart campus), Bachelor/Advanced Diploma of Applied Science (Nautical Science) and (Marine Engineering); Master of Psychology (Clinical), Master of Physiotherapy, Master of Speech Pathology, Master of Occupational Therapy. Not available for fully online, foundation, non-award, micro-credential, single-unit or exchange/study-abroad study; government-sponsored students; articulation or International Pathway College entrants; offshore campuses or transnational-education partners (unless expressly approved); or students holding another UTAS tuition scholarship or external sponsorship. To keep the award you must remain enrolled full-time past each census date, meet academic progression requirements (any AN — Absent Deemed Failed — result counts as not meeting progression) and comply with student visa conditions; an approved deferral leads to reassessment.', 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/tasmanian-aurora-excellence-scholarship', '["All"]', 'Merit-based', 'Partial tuition (50% fee reduction)', NULL, NULL, NULL, NULL, 'No fixed IELTS score is published for this scholarship; English requirements are set at course level (check the official course page for your programme).', '["University of Tasmania offer for an eligible course (the Aurora application is by invitation after the offer)","Aurora scholarship application form (link sent to invited students by email)","Personal statement of 300-500 words","Interview (shortlisted applicants)"]', 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/tasmanian-aurora-excellence-scholarship', '2026-09-14', '2026-11-15', 'fixed', NULL, NULL, '[{"batch":1,"name":"Semester 1, 2027","opening":"2026-09-14","deadline":"2026-11-15","status":"open"},{"batch":2,"name":"Semester 2, 2027","opening":null,"deadline":"2027-04-30","status":"not_yet_open"}]', 'annual', 'Mid-September for Semester 1 entry (14 September 2026 for Semester 1 2027); Semester 2 2027 opening to be confirmed', '15 November 2026 (Semester 1 2027) and 30 April 2027 (Semester 2 2027)', 'open', '2026-10-30 04:00:00+05', '2026-10-30 04:00:00+05', 'verified', 10, 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/tasmanian-aurora-excellence-scholarship', 'NEW in Enrichment Batch 40 (2026-10-30), written from the first-hand read of the university''s official Tasmanian Aurora Excellence Scholarship page (source 3182, including key dates, academic equivalency tables and the 2027 Terms and Conditions); the scheme heads UTAS''s 2027 international line-up on the hub (source 3183). deadline_date stores the first live close (15 November 2026, Semester 1 2027) with the two published rounds in the rounds JSON, mirroring the multi-round convention of records 573/978; the Semester 2 2027 opening is published as TBC, so no opening date is asserted for batch 2. Published rounds cover students commencing in 2027; recurrence is stored as annual because the award runs by semester intakes, but rounds beyond 2027 were not published on the page read. Amount convention mirrors records 676/761: the published percentage reduction stored as award_amount=50 (AUD, per year, variable) with a 0 USD value. min_gpa/min_ielts left NULL: the academic floor is an ATAR-90-equivalent / scale-table minimum (e.g. 3.7 on a 4.0 scale, 6.5/7 on the UTAS scale), which is scale-ambiguous and is recorded in the narrative. The page body once refers to the award as the "Tasmanian Excellence Scholarship"; the page title (Aurora Excellence) is used here.', true, 290, 50, 'AUD', 'year', 'variable');

-- 4) Retire 761 (TIS discontinued); mark its university side row unavailable
UPDATE scholarships SET is_active = false, application_status = 'closed', deadline_date = NULL, award_amount = NULL, award_currency = NULL, award_period = NULL, award_basis = NULL, amount_usd_value = 0, recurrence = 'none', deadline = 'Closed: the Tasmanian International Scholarship is no longer offered to new students. From the 2027 scholarship line-up the automatically-assessed merit route is the Tasmanian International Merit Scholarship (30%, record 1004), with the competitive Tasmanian Aurora Excellence Scholarship (50%, record 1005) above it.', last_verified_at = '2026-10-30 04:00:00+05', last_updated_at = '2026-10-30 04:00:00+05', notes = COALESCE(notes, '') || ' BATCH 40 RETIREMENT (2026-10-30): the Batch-40 re-scope flagged by Pass 133 is resolved — TIS IS DISCONTINUED for new applicants. The current International Scholarships hub (source 3183, fetched first-hand today) lists the automatically-assessed 2027 line-up as Aurora Excellence (50%), International Merit (30%), International Alumni and Family (25%), Access (20%), partner-college 20% awards and the Maritime College bursary (25-30%); no award named Tasmanian International Scholarship appears, and the two successor scheme pages (sources 3181/3182) contain no TIS route for commencing students. This row is therefore retired (inactive, closed, award family nulled; description and source URL retained for audit). The two individually verified successor schemes were added as their own records in the same batch: 1004 (Tasmanian International Merit Scholarship, 30%, automatic) and 1005 (Tasmanian Aurora Excellence Scholarship, 50%, by invitation). This row was not rewritten into either successor: name, value and benchmark all changed, so rewriting would have falsified the audit trail. Nothing here asserts that existing TIS holders lose their awards — the retirement records only that the scheme is no longer published for new/commencing students. Do not revive under this name unless UTAS republishes a Tasmanian International Scholarship for a future intake.' WHERE id = 761 AND notes NOT LIKE '%BATCH 40%';
UPDATE university_scholarships SET availability_status = 'No', last_verified_at = '2026-10-30 04:00:00+05' WHERE id = 261;

