(721, 290, 1004, 'Tasmanian International Merit Scholarship', 'available', 'Merit-based (automatic assessment)', '30% reduction in registered tuition fees for the course duration (up to five years full-time equivalent)', true, false, 'Automatic merit assessment on admission — no separate application', 'Commencing international students in eligible full-time undergraduate/postgraduate coursework degrees are assessed automatically on their highest qualification (benchmark about 10 ATAR points above the course minimum; 3.3 on a 4.0 GPA scale) and told in the offer letter; selected excluded courses (medicine, nautical/marine engineering, clinical psychology, physiotherapy, speech pathology, occupational therapy); English is set at course level.', 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/tasmanian-international-merit-scholarship', 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/tasmanian-international-merit-scholarship', 'verified', '2026-10-30 04:00:00+05'),
(722, 290, 1005, 'Tasmanian Aurora Excellence Scholarship', 'available', 'Merit-based (competitive, by invitation)', '50% reduction in registered tuition fees for the course duration (up to five years full-time equivalent)', true, false, 'Top-tier competitive award: 90 ATAR-equivalent floor plus personal statement and interview', 'International students commencing first year from 2027 who are Merit-eligible and hold an offer are invited to apply (form, 300-500 word statement, interview). Semester 1 2027 closes 15 November 2026; Semester 2 2027 closes 30 April 2027. Strict academic minimums (90 ATAR equivalent; 3.7 on a 4.0 scale; 6.5/7 UTAS GPA); selected excluded courses; English is set at course level.', 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/tasmanian-aurora-excellence-scholarship', 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/tasmanian-aurora-excellence-scholarship', 'verified', '2026-10-30 04:00:00+05');

